USE `employee_management_system`;

START TRANSACTION;

-- ============================================================
-- EMS sample data seed
-- MySQL 8.x compatible
-- IMPORTANT:
-- - `EMP001` is reserved for the system administrator and is NOT inserted here.
-- - 1,000 sample employees (EMP002-EMP1001) are seeded with varied HR records.
-- - `refresh_tokens` are intentionally not seeded; they are generated by the app.
-- - `user_accounts` are intentionally not seeded in SQL because BCrypt hashes must be created with PasswordEncoder.
-- - The dev initializer bootstraps only the admin account; sample employees get no accounts.
-- ============================================================

-- 1) Departments
INSERT INTO `departments` (`code`, `name`, `description`, `active`)
VALUES
  ('IT', 'Information Technology', 'Application development, platform engineering, and enterprise support.', 1),
  ('HR', 'Human Resources', 'Talent acquisition, employee relations, and workforce administration.', 1),
  ('FIN', 'Finance', 'Financial reporting, controls, budgeting, and payroll operations.', 1),
  ('MKT', 'Marketing', 'Brand campaigns, demand generation, and customer acquisition.', 1),
  ('SAL', 'Sales', 'Business growth, client acquisition, and revenue operations.', 1),
  ('OPS', 'Operations', 'Business operations, process efficiency, and service delivery.', 1),
  ('QA', 'Quality Assurance', 'Testing, validation, and release readiness assurance.', 1),
  ('SEC', 'Security', 'Cybersecurity, identity governance, and enterprise risk controls.', 1),
  ('SUP', 'Support', 'Internal support operations and user assistance.', 1),
  ('PMO', 'Program Management Office', 'Portfolio planning, governance, and project oversight.', 1)
ON DUPLICATE KEY UPDATE
  `name` = VALUES(`name`),
  `description` = VALUES(`description`),
  `active` = VALUES(`active`);

-- 2) Work shifts
INSERT INTO `work_shifts` (`name`, `start_time`, `end_time`, `break_start_time`, `break_end_time`, `overnight`, `active`)
VALUES
  ('General Shift', '09:00:00', '18:00:00', '13:00:00', '14:00:00', 0, 1),
  ('Morning Shift', '08:00:00', '17:00:00', '13:00:00', '14:00:00', 0, 1),
  ('Evening Shift', '13:00:00', '22:00:00', '17:00:00', '18:00:00', 0, 1),
  ('Night Shift', '21:00:00', '06:00:00', '02:00:00', '03:00:00', 1, 1),
  ('Flexible Shift', '10:00:00', '19:00:00', '14:00:00', '15:00:00', 0, 1)
ON DUPLICATE KEY UPDATE
  `start_time` = VALUES(`start_time`),
  `end_time` = VALUES(`end_time`),
  `break_start_time` = VALUES(`break_start_time`),
  `break_end_time` = VALUES(`break_end_time`),
  `overnight` = VALUES(`overnight`),
  `active` = VALUES(`active`);

-- 3) Leave types
INSERT INTO `leave_types` (`code`, `name`, `max_days`, `paid_leave`, `active`, `description`)
VALUES
  ('CL', 'Casual Leave', 12, 1, 1, 'Short-duration personal leave for urgent family and personal matters.'),
  ('SL', 'Sick Leave', 10, 1, 1, 'Medical leave for health recovery and treatment.'),
  ('PL', 'Privilege Leave', 18, 1, 1, 'Earned annual leave for planned personal leave.'),
  ('EL', 'Earned Leave', 15, 1, 1, 'Accumulated leave available for rest or personal use.'),
  ('LWP', 'Leave Without Pay', 30, 0, 1, 'Unpaid leave granted on approved request.'),
  ('ML', 'Maternity Leave', 180, 1, 1, 'Paid maternity leave for eligible employees.'),
  ('PTL', 'Paternity Leave', 15, 1, 1, 'Paternity leave for new fathers.'),
  ('WFH', 'Work From Home', 30, 1, 1, 'Temporary remote work arrangement for approved situations.')
ON DUPLICATE KEY UPDATE
  `name` = VALUES(`name`),
  `max_days` = VALUES(`max_days`),
  `paid_leave` = VALUES(`paid_leave`),
  `active` = VALUES(`active`),
  `description` = VALUES(`description`);

-- 4) Salary components
INSERT INTO `salary_components` (`code`, `name`, `type`, `description`, `active`)
VALUES
  ('BASIC', 'Basic Salary', 'EARNING', 'Monthly base salary before allowances and deductions.', 1),
  ('HRA', 'House Rent Allowance', 'EARNING', 'Accommodation support included in monthly gross pay.', 1),
  ('CONVEYANCE', 'Conveyance', 'EARNING', 'Travel allowance for work-related commuting.', 1),
  ('MEDICAL', 'Medical Allowance', 'EARNING', 'Healthcare support benefit for employees.', 1),
  ('SPECIAL', 'Special Allowance', 'EARNING', 'Performance-linked or role-based special payout.', 1),
  ('BONUS', 'Bonus', 'EARNING', 'Yearly or periodic performance bonus.', 1),
  ('PF', 'Provident Fund', 'DEDUCTION', 'Employee provident fund contribution.', 1),
  ('TDS', 'Tax Deducted at Source', 'DEDUCTION', 'Income tax deducted from payroll.', 1),
  ('PROF_TAX', 'Professional Tax', 'DEDUCTION', 'State professional tax deduction.', 1),
  ('ESI', 'Employee State Insurance', 'DEDUCTION', 'Insurance deduction as per statutory rules.', 1),
  ('LOAN', 'Loan Recovery', 'DEDUCTION', 'Recovery of company-provided loan or advance.', 1),
  ('OTHER_DED', 'Other Deduction', 'DEDUCTION', 'Miscellaneous deduction adjustments.', 1)
ON DUPLICATE KEY UPDATE
  `name` = VALUES(`name`),
  `type` = VALUES(`type`),
  `description` = VALUES(`description`),
  `active` = VALUES(`active`);

