-- Add 900 varied employees (EMP102-EMP1001) to bring the sample employee count to 1,000.
-- A temporary 1-900 sequence drives the employee and related sample records below.
DROP TEMPORARY TABLE IF EXISTS `ems_sample_numbers`;
CREATE TEMPORARY TABLE `ems_sample_numbers` (`n` INT NOT NULL PRIMARY KEY);
INSERT INTO `ems_sample_numbers` (`n`)
SELECT 1 + hundreds.digit * 100 + tens.digit * 10 + ones.digit
FROM
  (SELECT 0 AS digit UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4
   UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) hundreds
CROSS JOIN
  (SELECT 0 AS digit UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4
   UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) tens
CROSS JOIN
  (SELECT 0 AS digit UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4
   UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) ones
WHERE 1 + hundreds.digit * 100 + tens.digit * 10 + ones.digit <= 900;

INSERT INTO `employees` (
  `employee_code`, `first_name`, `last_name`, `email`, `phone`, `date_of_birth`, `gender`,
  `joining_date`, `designation`, `employment_type`, `employment_status`, `salary`,
  `department_id`, `shift_id`
)
SELECT
  CONCAT('EMP', numbers.n + 101),
  CASE MOD(numbers.n, 12)
    WHEN 0 THEN 'Aarav' WHEN 1 THEN 'Diya' WHEN 2 THEN 'Rohan' WHEN 3 THEN 'Meera'
    WHEN 4 THEN 'Vivaan' WHEN 5 THEN 'Ishita' WHEN 6 THEN 'Kabir' WHEN 7 THEN 'Ananya'
    WHEN 8 THEN 'Aditya' WHEN 9 THEN 'Nisha' WHEN 10 THEN 'Arjun' ELSE 'Ritika'
  END,
  CASE MOD(numbers.n, 12)
    WHEN 0 THEN 'Sharma' WHEN 1 THEN 'Patel' WHEN 2 THEN 'Iyer' WHEN 3 THEN 'Nair'
    WHEN 4 THEN 'Singh' WHEN 5 THEN 'Rao' WHEN 6 THEN 'Menon' WHEN 7 THEN 'Verma'
    WHEN 8 THEN 'Joshi' WHEN 9 THEN 'Kulkarni' WHEN 10 THEN 'Desai' ELSE 'Bhatt'
  END,
  CONCAT('employee.', LPAD(numbers.n + 101, 4, '0'), '@ems.example'),
  CONCAT('+9198', LPAD(numbers.n + 10000000, 8, '0')),
  DATE_ADD('1970-01-01', INTERVAL (MOD(numbers.n * 379, 10000)) DAY),
  CASE MOD(numbers.n, 3) WHEN 0 THEN 'MALE' WHEN 1 THEN 'FEMALE' ELSE 'OTHER' END,
  DATE_ADD('2016-01-01', INTERVAL (MOD(numbers.n * 47, 3650)) DAY),
  CASE MOD(numbers.n, 10)
    WHEN 0 THEN 'Software Engineer' WHEN 1 THEN 'HR Executive'
    WHEN 2 THEN 'Finance Analyst' WHEN 3 THEN 'Sales Executive'
    WHEN 4 THEN 'Marketing Specialist' WHEN 5 THEN 'Operations Analyst'
    WHEN 6 THEN 'Quality Engineer' WHEN 7 THEN 'Security Analyst'
    WHEN 8 THEN 'Support Engineer' ELSE 'Project Coordinator'
  END,
  CASE MOD(numbers.n, 5)
    WHEN 0 THEN 'FULL_TIME' WHEN 1 THEN 'FULL_TIME'
    WHEN 2 THEN 'CONTRACT' WHEN 3 THEN 'PART_TIME' ELSE 'INTERN'
  END,
  CASE MOD(numbers.n, 40)
    WHEN 0 THEN 'ON_LEAVE' WHEN 1 THEN 'SUSPENDED' WHEN 2 THEN 'RESIGNED'
    WHEN 3 THEN 'TERMINATED' WHEN 4 THEN 'RETIRED' ELSE 'ACTIVE'
  END,
  45000.00 + MOD(numbers.n * 791, 120000),
  MOD(numbers.n - 1, 10) + 1,
  MOD(numbers.n - 1, 5) + 1
FROM `ems_sample_numbers` numbers
ON DUPLICATE KEY UPDATE
  `first_name` = VALUES(`first_name`),
  `last_name` = VALUES(`last_name`),
  `email` = VALUES(`email`),
  `phone` = VALUES(`phone`),
  `date_of_birth` = VALUES(`date_of_birth`),
  `gender` = VALUES(`gender`),
  `joining_date` = VALUES(`joining_date`),
  `designation` = VALUES(`designation`),
  `employment_type` = VALUES(`employment_type`),
  `employment_status` = VALUES(`employment_status`),
  `salary` = VALUES(`salary`),
  `department_id` = VALUES(`department_id`),
  `shift_id` = VALUES(`shift_id`);

