-- 7) Employee addresses (one per employee)
INSERT INTO `employee_addresses` (`address_line1`, `address_line2`, `city`, `state`, `postal_code`, `country`, `employee_id`)
SELECT
  CONCAT('House No. ', MOD(e.id, 120) + 18, ', Sector ', MOD(e.id, 9) + 1),
  CASE MOD(e.id, 5)
    WHEN 0 THEN 'Near Metro Station'
    WHEN 1 THEN 'Near Community Park'
    WHEN 2 THEN 'Near Tech Park'
    WHEN 3 THEN 'Near Market Road'
    ELSE 'Near School Complex'
  END,
  CASE MOD(e.id, 11)
    WHEN 0 THEN 'Delhi' WHEN 1 THEN 'Noida' WHEN 2 THEN 'Greater Noida' WHEN 3 THEN 'Gurugram' WHEN 4 THEN 'Faridabad' WHEN 5 THEN 'Ghaziabad'
    WHEN 6 THEN 'Bengaluru' WHEN 7 THEN 'Mumbai' WHEN 8 THEN 'Pune' WHEN 9 THEN 'Hyderabad' ELSE 'Chennai'
  END,
  CASE MOD(e.id, 11)
    WHEN 0 THEN 'Delhi' WHEN 1 THEN 'Uttar Pradesh' WHEN 2 THEN 'Uttar Pradesh' WHEN 3 THEN 'Haryana' WHEN 4 THEN 'Haryana' WHEN 5 THEN 'Uttar Pradesh'
    WHEN 6 THEN 'Karnataka' WHEN 7 THEN 'Maharashtra' WHEN 8 THEN 'Maharashtra' WHEN 9 THEN 'Telangana' ELSE 'Tamil Nadu'
  END,
  LPAD(CAST(110000 + MOD(e.id * 173, 70000) AS CHAR), 6, '0'),
  'India',
  e.id
FROM `employees` e
WHERE e.id IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM `employee_addresses` ea WHERE ea.employee_id = e.id);

