-- 9) Employee project assignments (approximately 2,500 assignments)
INSERT INTO `employee_projects` (`employee_id`, `project_id`, `project_role`, `allocation_percentage`, `assigned_date`, `released_date`, `active`)
SELECT
  e.id AS employee_id,
  p.id AS project_id,
  CASE MOD(e.id + p.id, 8)
    WHEN 0 THEN 'Developer'
    WHEN 1 THEN 'Backend Developer'
    WHEN 2 THEN 'Frontend Developer'
    WHEN 3 THEN 'QA Engineer'
    WHEN 4 THEN 'Business Analyst'
    WHEN 5 THEN 'DevOps Engineer'
    WHEN 6 THEN 'Project Coordinator'
    ELSE 'Support Engineer'
  END AS project_role,
  CASE MOD(e.id + p.id, 4)
    WHEN 0 THEN 25
    WHEN 1 THEN 50
    WHEN 2 THEN 75
    ELSE 100
  END AS allocation_percentage,
  DATE('2026-01-15') AS assigned_date,
  NULL AS released_date,
  1 AS active
FROM `employees` e
JOIN `projects` p ON MOD(e.id + p.id, 4) = 0
WHERE NOT EXISTS (SELECT 1 FROM `employee_projects` ep WHERE ep.employee_id = e.id AND ep.project_id = p.id);

-- 10) Employee salaries (multiple component records per employee)
INSERT INTO `employee_salaries` (`employee_id`, `salary_component_id`, `amount`, `effective_from`, `effective_to`, `active`)
SELECT
  e.id,
  sc.id,
  CASE sc.code
    WHEN 'BASIC' THEN ROUND(e.salary * 0.50, 2)
    WHEN 'HRA' THEN ROUND(e.salary * 0.22, 2)
    WHEN 'CONVEYANCE' THEN 2400.00
    WHEN 'MEDICAL' THEN 3000.00
    WHEN 'SPECIAL' THEN ROUND(e.salary * 0.14, 2)
    WHEN 'BONUS' THEN ROUND(e.salary * 0.08, 2)
    WHEN 'PF' THEN ROUND(e.salary * 0.12, 2)
    WHEN 'TDS' THEN CASE WHEN e.salary > 100000 THEN ROUND(e.salary * 0.08, 2) ELSE 0.00 END
    WHEN 'PROF_TAX' THEN CASE WHEN e.salary > 70000 THEN 2000.00 ELSE 0.00 END
    WHEN 'ESI' THEN CASE WHEN e.salary < 21000 THEN ROUND(e.salary * 0.018, 2) ELSE 0.00 END
    WHEN 'LOAN' THEN CASE WHEN MOD(e.id, 7) = 0 THEN 1500.00 ELSE 0.00 END
    WHEN 'OTHER_DED' THEN CASE WHEN MOD(e.id, 9) = 0 THEN 800.00 ELSE 0.00 END
    ELSE 0.00
  END AS amount,
  DATE('2026-04-01') AS effective_from,
  NULL AS effective_to,
  1 AS active
FROM `employees` e
JOIN `salary_components` sc ON sc.code IN ('BASIC', 'HRA', 'CONVEYANCE', 'MEDICAL', 'SPECIAL', 'BONUS', 'PF', 'TDS', 'PROF_TAX', 'ESI', 'LOAN', 'OTHER_DED')
WHERE NOT EXISTS (
  SELECT 1
  FROM `employee_salaries` es
  WHERE es.employee_id = e.id
    AND es.salary_component_id = sc.id
    AND es.effective_from = DATE('2026-04-01')
);

-- 11) Attendance for September 2026 (weekdays only)
INSERT INTO `attendance` (`employee_id`, `attendance_date`, `check_in`, `check_out`, `working_hours`, `status`, `remarks`)
WITH RECURSIVE `calendar` AS (
  SELECT DATE('2026-09-01') AS `d`
  UNION ALL
  SELECT DATE_ADD(`d`, INTERVAL 1 DAY)
  FROM `calendar`
  WHERE `d` < DATE('2026-09-30')
)
SELECT
  e.id AS employee_id,
  c.d AS attendance_date,
  TIMESTAMP(c.d, CASE MOD((e.id + DAY(c.d)), 8)
    WHEN 0 THEN '09:15:00'
    WHEN 1 THEN '09:00:00'
    WHEN 2 THEN '09:30:00'
    WHEN 3 THEN '08:55:00'
    WHEN 4 THEN '10:00:00'
    WHEN 5 THEN '09:20:00'
    WHEN 6 THEN '08:45:00'
    ELSE '09:10:00'
  END) AS check_in,
  TIMESTAMP(c.d, CASE MOD((e.id + DAY(c.d)), 8)
    WHEN 0 THEN '18:15:00'
    WHEN 1 THEN '18:00:00'
    WHEN 2 THEN '18:30:00'
    WHEN 3 THEN '17:55:00'
    WHEN 4 THEN '19:00:00'
    WHEN 5 THEN '18:20:00'
    WHEN 6 THEN '17:45:00'
    ELSE '18:10:00'
  END) AS check_out,
  CASE MOD((e.id + DAY(c.d)), 8)
    WHEN 0 THEN 8.25
    WHEN 1 THEN 8.50
    WHEN 2 THEN 7.50
    WHEN 3 THEN 8.00
    WHEN 4 THEN 9.00
    WHEN 5 THEN 8.25
    WHEN 6 THEN 7.50
    ELSE 8.00
  END AS working_hours,
  CASE MOD((e.id + DAY(c.d)), 8)
    WHEN 0 THEN 'PRESENT'
    WHEN 1 THEN 'LATE'
    WHEN 2 THEN 'HALF_DAY'
    WHEN 3 THEN 'PRESENT'
    WHEN 4 THEN 'WORK_FROM_HOME'
    WHEN 5 THEN 'ABSENT'
    WHEN 6 THEN 'ON_LEAVE'
    ELSE 'PRESENT'
  END AS status,
  CASE MOD((e.id + DAY(c.d)), 8)
    WHEN 0 THEN 'On time and project delivery completed.'
    WHEN 1 THEN 'Slight delay due to traffic congestion.'
    WHEN 2 THEN 'Half day leave due to medical follow-up.'
    WHEN 3 THEN 'Regular working day.'
    WHEN 4 THEN 'Remote working day due to system maintenance.'
    WHEN 5 THEN 'Absent due to personal reasons.'
    WHEN 6 THEN 'Approved leave for family commitment.'
    ELSE 'Normal attendance and focused workday.'
  END AS remarks
FROM `employees` e
JOIN `calendar` c ON DAYOFWEEK(c.d) BETWEEN 2 AND 6
WHERE NOT EXISTS (
  SELECT 1
  FROM `attendance` a
  WHERE a.employee_id = e.id
    AND a.attendance_date = c.d
);

-- 12) Leave requests (approx. 180)
INSERT INTO `leave_requests` (`employee_id`, `leave_type_id`, `start_date`, `end_date`, `total_days`, `reason`, `status`, `approved_by`, `applied_at`, `approved_at`, `rejection_reason`)
WITH RECURSIVE `seq` AS (
  SELECT 1 AS `n`
  UNION ALL
  SELECT `n` + 1 FROM `seq` WHERE `n` < 180
)
SELECT
  e.id AS employee_id,
  ((s.n - 1) % 8) + 1 AS leave_type_id,
  DATE('2026-09-01') + INTERVAL ((s.n - 1) % 18) DAY AS start_date,
  DATE('2026-09-01') + INTERVAL ((s.n - 1) % 18 + MOD(s.n, 3) + 1) DAY AS end_date,
  CASE WHEN DATE('2026-09-01') + INTERVAL ((s.n - 1) % 18 + MOD(s.n, 3) + 1) DAY >= DATE('2026-09-01') + INTERVAL ((s.n - 1) % 18) DAY THEN DATEDIFF(DATE('2026-09-01') + INTERVAL ((s.n - 1) % 18 + MOD(s.n, 3) + 1) DAY, DATE('2026-09-01') + INTERVAL ((s.n - 1) % 18) DAY) + 1 ELSE 1 END AS total_days,
  CASE MOD(s.n, 6)
    WHEN 0 THEN 'Family emergency and travel requirement.'
    WHEN 1 THEN 'Health consultation and recovery time.'
    WHEN 2 THEN 'Personal family commitment.'
    WHEN 3 THEN 'Planned vacation and rest.'
    WHEN 4 THEN 'Work from home due to connectivity issue.'
    ELSE 'Urgent personal reason.'
  END AS reason,
  CASE MOD(s.n, 5)
    WHEN 0 THEN 'PENDING'
    WHEN 1 THEN 'APPROVED'
    WHEN 2 THEN 'REJECTED'
    WHEN 3 THEN 'CANCELLED'
    ELSE 'APPROVED'
  END AS status,
  CASE MOD(s.n, 5)
    WHEN 1 THEN e.manager_id
    WHEN 2 THEN e.manager_id
    ELSE NULL
  END AS approved_by,
  TIMESTAMP(DATE('2026-09-01') + INTERVAL ((s.n - 1) % 18) DAY, '09:00:00') AS applied_at,
  CASE MOD(s.n, 5)
    WHEN 1 THEN TIMESTAMP(DATE('2026-09-01') + INTERVAL ((s.n - 1) % 18 + 1) DAY, '12:00:00')
    WHEN 2 THEN TIMESTAMP(DATE('2026-09-01') + INTERVAL ((s.n - 1) % 18 + 1) DAY, '11:30:00')
    ELSE NULL
  END AS approved_at,
  CASE MOD(s.n, 5)
    WHEN 2 THEN 'Evidence not sufficient for leave approval in this cycle.'
    ELSE NULL
  END AS rejection_reason
FROM `seq` s
JOIN `employees` e ON e.employee_code = CONCAT('EMP', MOD(s.n - 1, 100) + 2)
WHERE NOT EXISTS (
  SELECT 1
  FROM `leave_requests` lr
  WHERE lr.employee_id = e.id
    AND lr.start_date = DATE('2026-09-01') + INTERVAL ((s.n - 1) % 18) DAY
);

-- 13) Payroll for July, August, and September 2026
INSERT INTO `payrolls` (`employee_id`, `pay_period_start`, `pay_period_end`, `basic_salary`, `allowances`, `deductions`, `gross_salary`, `net_salary`, `status`, `payment_date`)
SELECT
  e.id AS employee_id,
  p.pay_period_start,
  p.pay_period_end,
  ROUND(e.salary * 0.50, 2) AS basic_salary,
  ROUND(e.salary * 0.18, 2) AS allowances,
  ROUND(e.salary * 0.10, 2) AS deductions,
  ROUND(e.salary * 0.68, 2) AS gross_salary,
  ROUND(e.salary * 0.58, 2) AS net_salary,
  CASE MOD(e.id + p.period_offset, 4)
    WHEN 0 THEN 'PAID'
    WHEN 1 THEN 'PROCESSED'
    WHEN 2 THEN 'PENDING'
    ELSE 'FAILED'
  END AS status,
  CASE MOD(e.id + p.period_offset, 4)
    WHEN 0 THEN DATE_ADD(p.pay_period_end, INTERVAL 7 DAY)
    ELSE NULL
  END AS payment_date
FROM `employees` e
JOIN (
  SELECT DATE('2026-07-01') AS pay_period_start, DATE('2026-07-31') AS pay_period_end, 0 AS period_offset
  UNION ALL
  SELECT DATE('2026-08-01'), DATE('2026-08-31'), 1
  UNION ALL
  SELECT DATE('2026-09-01'), DATE('2026-09-30'), 2
) p
WHERE NOT EXISTS (
  SELECT 1
  FROM `payrolls` pr
  WHERE pr.employee_id = e.id
    AND pr.pay_period_start = p.pay_period_start
    AND pr.pay_period_end = p.pay_period_end
);

-- 14) Performance reviews (approx. 120)
INSERT INTO `performance_reviews` (`employee_id`, `reviewer_id`, `review_date`, `rating`, `strengths`, `improvements`, `comments`, `next_review_date`)
WITH RECURSIVE `seq` AS (
  SELECT 1 AS `n`
  UNION ALL
  SELECT `n` + 1 FROM `seq` WHERE `n` < 120
)
SELECT
  e.id AS employee_id,
  CASE MOD(s.n, 8)
    WHEN 0 THEN (SELECT `id` FROM `employees` WHERE `employee_code` = 'EMP002')
    WHEN 1 THEN (SELECT `id` FROM `employees` WHERE `employee_code` = 'EMP008')
    WHEN 2 THEN (SELECT `id` FROM `employees` WHERE `employee_code` = 'EMP012')
    WHEN 3 THEN (SELECT `id` FROM `employees` WHERE `employee_code` = 'EMP014')
    WHEN 4 THEN (SELECT `id` FROM `employees` WHERE `employee_code` = 'EMP016')
    WHEN 5 THEN (SELECT `id` FROM `employees` WHERE `employee_code` = 'EMP018')
    WHEN 6 THEN (SELECT `id` FROM `employees` WHERE `employee_code` = 'EMP030')
    ELSE (SELECT `id` FROM `employees` WHERE `employee_code` = 'EMP036')
  END AS reviewer_id,
  DATE('2026-09-15') + INTERVAL ((s.n - 1) % 15) DAY AS review_date,
  CASE MOD(s.n, 5)
    WHEN 0 THEN 'EXCEPTIONAL'
    WHEN 1 THEN 'EXCEEDS_EXPECTATIONS'
    WHEN 2 THEN 'MEETS_EXPECTATIONS'
    WHEN 3 THEN 'NEEDS_IMPROVEMENT'
    ELSE 'UNSATISFACTORY'
  END AS rating,
  'Strong ownership, reliable execution, and quality focus in routine work.' AS strengths,
  'Continue improving stakeholder communication and documentation consistency.' AS improvements,
  'Consistent delivery with a clear focus on team goals and business outcomes.' AS comments,
  DATE('2027-03-15') AS next_review_date
FROM `seq` s
JOIN `employees` e ON e.employee_code = CONCAT('EMP', MOD(s.n - 1, 100) + 2)
WHERE NOT EXISTS (
  SELECT 1
  FROM `performance_reviews` pr
  WHERE pr.employee_id = e.id
    AND pr.review_date = DATE('2026-09-15') + INTERVAL ((s.n - 1) % 15) DAY
);

-- 15) Employee documents (2 per employee, document types spread across accepted categories)
INSERT INTO `employee_documents` (`employee_id`, `document_type`, `file_name`, `file_url`, `document_number`, `uploaded_at`, `verified`)
WITH RECURSIVE `seq` AS (
  SELECT 1 AS `n`
  UNION ALL
  SELECT `n` + 1 FROM `seq` WHERE `n` < 200
)
SELECT
  e.id AS employee_id,
  CASE MOD(s.n, 9)
    WHEN 0 THEN 'AADHAAR'
    WHEN 1 THEN 'PAN'
    WHEN 2 THEN 'PASSPORT'
    WHEN 3 THEN 'DRIVING_LICENSE'
    WHEN 4 THEN 'EDUCATIONAL_CERTIFICATE'
    WHEN 5 THEN 'EXPERIENCE_LETTER'
    WHEN 6 THEN 'OFFER_LETTER'
    WHEN 7 THEN 'RESUME'
    ELSE 'OTHER'
  END AS document_type,
  CONCAT('doc_', LOWER(REPLACE(e.employee_code, 'EMP', 'emp')), '_', MOD(s.n, 7) + 1, '.pdf') AS file_name,
  CONCAT('https://cdn.example.com/docs/', LOWER(e.employee_code), '/', MOD(s.n, 7) + 1, '.pdf') AS file_url,
  CONCAT('DOC-', LPAD(s.n, 6, '0')) AS document_number,
  TIMESTAMP(DATE('2026-01-01') + INTERVAL ((s.n - 1) % 40) DAY, '10:00:00') AS uploaded_at,
  CASE WHEN MOD(s.n, 3) = 0 THEN 1 ELSE 0 END AS verified
FROM `seq` s
JOIN `employees` e ON e.employee_code = CONCAT('EMP', MOD(s.n - 1, 100) + 2)
WHERE NOT EXISTS (
  SELECT 1
  FROM `employee_documents` ed
  WHERE ed.employee_id = e.id
    AND ed.document_number = CONCAT('DOC-', LPAD(s.n, 6, '0'))
);

-- 16) Employee assets (approx. 120)
INSERT INTO `employee_assets` (`asset_name`, `asset_type`, `serial_number`, `employee_id`, `assigned_date`, `return_date`, `status`, `remarks`)
WITH RECURSIVE `seq` AS (
  SELECT 1 AS `n`
  UNION ALL
  SELECT `n` + 1 FROM `seq` WHERE `n` < 120
)
SELECT
  CASE MOD(s.n, 7)
    WHEN 0 THEN 'Laptop'
    WHEN 1 THEN 'Monitor'
    WHEN 2 THEN 'Mobile Phone'
    WHEN 3 THEN 'Headset'
    WHEN 4 THEN 'Keyboard'
    WHEN 5 THEN 'Mouse'
    ELSE 'Tablet'
  END AS asset_name,
  CASE MOD(s.n, 7)
    WHEN 0 THEN 'Computing'
    WHEN 1 THEN 'Display'
    WHEN 2 THEN 'Communication'
    WHEN 3 THEN 'Audio'
    WHEN 4 THEN 'Input'
    WHEN 5 THEN 'Input'
    ELSE 'Portable Device'
  END AS asset_type,
  CONCAT('ASSET-', LPAD(s.n, 5, '0')) AS serial_number,
  e.id AS employee_id,
  DATE('2026-02-01') + INTERVAL ((s.n - 1) % 90) DAY AS assigned_date,
  CASE WHEN MOD(s.n, 5) = 0 THEN DATE('2026-08-01') + INTERVAL ((s.n - 1) % 20) DAY ELSE NULL END AS return_date,
  CASE MOD(s.n, 5)
    WHEN 0 THEN 'RETURNED'
    WHEN 1 THEN 'ASSIGNED'
    WHEN 2 THEN 'UNDER_REPAIR'
    WHEN 3 THEN 'DAMAGED'
    ELSE 'ASSIGNED'
  END AS status,
  CASE MOD(s.n, 5)
    WHEN 0 THEN 'Returned after replacement due to business need.'
    WHEN 1 THEN 'Assigned to active team member.'
    WHEN 2 THEN 'Sent for repair with vendor coordination.'
    WHEN 3 THEN 'Minor damage reported and flagged for vendor review.'
    ELSE 'Standard corporate asset issued.'
  END AS remarks
FROM `seq` s
JOIN `employees` e ON e.employee_code = CONCAT('EMP', MOD(s.n - 1, 100) + 2)
WHERE NOT EXISTS (
  SELECT 1
  FROM `employee_assets` ea
  WHERE ea.serial_number = CONCAT('ASSET-', LPAD(s.n, 5, '0'))
);

-- Additional varied related records for generated employees (EMP102-EMP1001).
INSERT INTO `leave_requests` (
  `employee_id`, `leave_type_id`, `start_date`, `end_date`, `total_days`,
  `reason`, `status`, `approved_by`, `applied_at`, `approved_at`, `rejection_reason`
)
SELECT
  e.id,
  MOD(numbers.n - 1, 8) + 1,
  DATE_ADD('2026-01-01', INTERVAL (MOD(numbers.n * 7, 240)) DAY),
  DATE_ADD('2026-01-01', INTERVAL (MOD(numbers.n * 7, 240) + MOD(numbers.n, 4)) DAY),
  MOD(numbers.n, 4) + 1,
  CASE MOD(numbers.n, 5)
    WHEN 0 THEN 'Family commitment and travel.'
    WHEN 1 THEN 'Medical appointment and recovery.'
    WHEN 2 THEN 'Personal leave requested in advance.'
    WHEN 3 THEN 'Planned vacation.'
    ELSE 'Temporary remote work arrangement.'
  END,
  CASE MOD(numbers.n, 4)
    WHEN 0 THEN 'PENDING' WHEN 1 THEN 'APPROVED'
    WHEN 2 THEN 'REJECTED' ELSE 'CANCELLED'
  END,
  CASE WHEN MOD(numbers.n, 4) IN (1, 2) THEN e.manager_id ELSE NULL END,
  TIMESTAMP(DATE_ADD('2026-01-01', INTERVAL (MOD(numbers.n * 7, 240) - 14) DAY), '09:00:00'),
  CASE WHEN MOD(numbers.n, 4) IN (1, 2)
    THEN TIMESTAMP(DATE_ADD('2026-01-01', INTERVAL (MOD(numbers.n * 7, 240) - 7) DAY), '12:00:00')
    ELSE NULL
  END,
  CASE WHEN MOD(numbers.n, 4) = 2
    THEN 'Request declined after review of team coverage.'
    ELSE NULL
  END
FROM `ems_sample_numbers` numbers
JOIN `employees` e ON e.employee_code = CONCAT('EMP', numbers.n + 101)
WHERE NOT EXISTS (
  SELECT 1
  FROM `leave_requests` lr
  WHERE lr.employee_id = e.id
    AND lr.start_date = DATE_ADD('2026-01-01', INTERVAL (MOD(numbers.n * 7, 240)) DAY)
);

INSERT INTO `performance_reviews` (
  `employee_id`, `reviewer_id`, `review_date`, `rating`, `strengths`,
  `improvements`, `comments`, `next_review_date`
)
SELECT
  e.id,
  e.manager_id,
  DATE_ADD('2026-01-01', INTERVAL (MOD(numbers.n * 11, 240)) DAY),
  CASE MOD(numbers.n, 5)
    WHEN 0 THEN 'EXCEPTIONAL' WHEN 1 THEN 'EXCEEDS_EXPECTATIONS'
    WHEN 2 THEN 'MEETS_EXPECTATIONS' WHEN 3 THEN 'NEEDS_IMPROVEMENT'
    ELSE 'UNSATISFACTORY'
  END,
  'Demonstrates ownership, collaboration, and reliable delivery.',
  'Continue building domain expertise and documenting key decisions.',
  'Performance reviewed against role expectations and quarterly goals.',
  DATE_ADD('2026-01-01', INTERVAL (MOD(numbers.n * 11, 240) + 180) DAY)
FROM `ems_sample_numbers` numbers
JOIN `employees` e ON e.employee_code = CONCAT('EMP', numbers.n + 101)
WHERE NOT EXISTS (
  SELECT 1
  FROM `performance_reviews` pr
  WHERE pr.employee_id = e.id
    AND pr.review_date = DATE_ADD('2026-01-01', INTERVAL (MOD(numbers.n * 11, 240)) DAY)
);

INSERT INTO `employee_documents` (
  `employee_id`, `document_type`, `file_name`, `file_url`,
  `document_number`, `uploaded_at`, `verified`
)
SELECT
  e.id,
  CASE MOD(numbers.n + variants.variant, 9)
    WHEN 0 THEN 'AADHAAR' WHEN 1 THEN 'PAN' WHEN 2 THEN 'PASSPORT'
    WHEN 3 THEN 'DRIVING_LICENSE' WHEN 4 THEN 'EDUCATIONAL_CERTIFICATE'
    WHEN 5 THEN 'EXPERIENCE_LETTER' WHEN 6 THEN 'OFFER_LETTER'
    WHEN 7 THEN 'RESUME' ELSE 'OTHER'
  END,
  CONCAT(LOWER(e.employee_code), '_document_', variants.variant, '.pdf'),
  CONCAT('https://cdn.example.com/docs/', LOWER(e.employee_code), '/document_', variants.variant, '.pdf'),
  CONCAT('DOC-', e.employee_code, '-', variants.variant),
  TIMESTAMP(DATE_ADD('2026-01-01', INTERVAL (MOD(numbers.n + variants.variant, 240)) DAY), '10:00:00'),
  MOD(numbers.n + variants.variant, 3) = 0
FROM `ems_sample_numbers` numbers
JOIN `employees` e ON e.employee_code = CONCAT('EMP', numbers.n + 101)
CROSS JOIN (SELECT 1 AS variant UNION ALL SELECT 2 AS variant) variants
WHERE NOT EXISTS (
  SELECT 1
  FROM `employee_documents` ed
  WHERE ed.document_number = CONCAT('DOC-', e.employee_code, '-', variants.variant)
);

INSERT INTO `employee_assets` (
  `asset_name`, `asset_type`, `serial_number`, `employee_id`,
  `assigned_date`, `return_date`, `status`, `remarks`
)
SELECT
  CASE MOD(numbers.n, 6)
    WHEN 0 THEN 'Laptop' WHEN 1 THEN 'Monitor' WHEN 2 THEN 'Mobile Phone'
    WHEN 3 THEN 'Headset' WHEN 4 THEN 'Keyboard' ELSE 'Tablet'
  END,
  CASE MOD(numbers.n, 6)
    WHEN 0 THEN 'Computing' WHEN 1 THEN 'Display'
    WHEN 2 THEN 'Communication' WHEN 3 THEN 'Audio'
    WHEN 4 THEN 'Input' ELSE 'Portable Device'
  END,
  CONCAT('EMS-ASSET-', e.employee_code),
  e.id,
  DATE_ADD('2026-01-01', INTERVAL (MOD(numbers.n * 13, 240)) DAY),
  CASE WHEN MOD(numbers.n, 5) = 0
    THEN DATE_ADD(
      DATE_ADD('2026-01-01', INTERVAL (MOD(numbers.n * 13, 240)) DAY),
      INTERVAL 30 DAY
    )
    ELSE NULL
  END,
  CASE MOD(numbers.n, 5)
    WHEN 0 THEN 'RETURNED' WHEN 1 THEN 'ASSIGNED'
    WHEN 2 THEN 'UNDER_REPAIR' WHEN 3 THEN 'DAMAGED' ELSE 'ASSIGNED'
  END,
  CASE MOD(numbers.n, 5)
    WHEN 0 THEN 'Returned after replacement.'
    WHEN 1 THEN 'Assigned for daily work.'
    WHEN 2 THEN 'Sent for vendor repair.'
    WHEN 3 THEN 'Damage reported for review.'
    ELSE 'Standard corporate asset assignment.'
  END
FROM `ems_sample_numbers` numbers
JOIN `employees` e ON e.employee_code = CONCAT('EMP', numbers.n + 101)
WHERE NOT EXISTS (
  SELECT 1
  FROM `employee_assets` ea
  WHERE ea.serial_number = CONCAT('EMS-ASSET-', e.employee_code)
);

DROP TEMPORARY TABLE `ems_sample_numbers`;

