-- 19) Relationship verification queries
SELECT
  e.employee_code,
  CONCAT(e.first_name, ' ', e.last_name) AS employee_name,
  d.name AS department,
  e.designation
FROM `employees` e
LEFT JOIN `departments` d ON d.id = e.department_id
ORDER BY e.id;

SELECT
  e.employee_code,
  CONCAT(e.first_name, ' ', e.last_name) AS employee_name,
  m.employee_code AS manager_code,
  CONCAT(m.first_name, ' ', m.last_name) AS manager_name
FROM `employees` e
LEFT JOIN `employees` m ON m.id = e.manager_id
ORDER BY e.id;

SELECT
  e.employee_code,
  CONCAT(e.first_name, ' ', e.last_name) AS employee_name,
  ws.name AS work_shift,
  ws.start_time,
  ws.end_time
FROM `employees` e
LEFT JOIN `work_shifts` ws ON ws.id = e.shift_id
ORDER BY e.id;

SELECT
  e.employee_code,
  CONCAT(e.first_name, ' ', e.last_name) AS employee_name,
  ua.username,
  ua.role
FROM `employees` e
LEFT JOIN `user_accounts` ua ON ua.employee_id = e.id
ORDER BY e.id;

SELECT
  e.employee_code,
  CONCAT(e.first_name, ' ', e.last_name) AS employee_name,
  p.code AS project_code,
  p.name AS project_name,
  ep.project_role,
  ep.allocation_percentage
FROM `employee_projects` ep
JOIN `employees` e ON e.id = ep.employee_id
JOIN `projects` p ON p.id = ep.project_id
ORDER BY e.id, p.id;

SELECT
  e.employee_code,
  CONCAT(e.first_name, ' ', e.last_name) AS employee_name,
  a.attendance_date,
  a.status,
  a.working_hours
FROM `attendance` a
JOIN `employees` e ON e.id = a.employee_id
ORDER BY a.attendance_date, e.id;

SELECT
  e.employee_code,
  CONCAT(e.first_name, ' ', e.last_name) AS employee_name,
  lt.name AS leave_type,
  lr.start_date,
  lr.end_date,
  lr.status
FROM `leave_requests` lr
JOIN `employees` e ON e.id = lr.employee_id
JOIN `leave_types` lt ON lt.id = lr.leave_type_id
ORDER BY lr.start_date, e.id;

SELECT
  e.employee_code,
  CONCAT(e.first_name, ' ', e.last_name) AS employee_name,
  p.pay_period_start,
  p.pay_period_end,
  p.net_salary,
  p.status
FROM `payrolls` p
JOIN `employees` e ON e.id = p.employee_id
ORDER BY p.pay_period_start, e.id;

SELECT
  e.employee_code,
  CONCAT(e.first_name, ' ', e.last_name) AS employee_name,
  pr.review_date,
  pr.rating,
  pr.comments
FROM `performance_reviews` pr
JOIN `employees` e ON e.id = pr.employee_id
ORDER BY pr.review_date, e.id;

SELECT
  e.employee_code,
  CONCAT(e.first_name, ' ', e.last_name) AS employee_name,
  ed.document_type,
  ed.file_name,
  ed.document_number
FROM `employee_documents` ed
JOIN `employees` e ON e.id = ed.employee_id
ORDER BY e.id, ed.document_type;

SELECT
  e.employee_code,
  CONCAT(e.first_name, ' ', e.last_name) AS employee_name,
  ea.asset_name,
  ea.asset_type,
  ea.serial_number,
  ea.status
FROM `employee_assets` ea
LEFT JOIN `employees` e ON e.id = ea.employee_id
ORDER BY e.id, ea.asset_name;

COMMIT;

